Create Procedure [dbo].[PedPenDetalle] as SELECT PC.ID,PC.ORDER_DATE,PC.CUSTOMER_ID,PC.CUSTOMER_NAME,PC.VAT_REGISTRATION,PC.CURRENCY_ID,PC.AMOUNT_VAT,PC.AMOUNT,PC.SELL_RATE,PD.ITEM,    PD.PART_ID , PD.PART_DESCRIPTION, PD.QTY, PD.UNIT, PD.PRICE_SALES, PD.AMOUNT_TAX, PD.AMOUNT_US, PD.AMOUNT from [BDNOVAQ].dbo.ORDERS PC inner join [BDNOVAQ].dbo.ORDER_LINE PD  ON PC.ID=PD.ID WHERE PC.STATUS='V' and PC.CUSTOMER_ID>='001' and PC.CUSTOMER_ID<='002' and PC.CADUCATE_DATE>='01/04/2008' and PC.CADUCATE_DATE<='30/05/2008' and PC.STATUS_ORDER='AUTORIZADO'  GROUP BY PC.ID,PC.ORDER_DATE,PC.CUSTOMER_ID,PC.CUSTOMER_NAME,PC.VAT_REGISTRATION,PC.CURRENCY_ID,PC.AMOUNT_VAT,PC.AMOUNT,PC.SELL_RATE,PD.ITEM,PD.PART_ID , PD.PART_DESCRIPTION, PD.QTY, PD.UNIT, PD.PRICE_SALES, PD.AMOUNT_TAX, PD.AMOUNT_US, PD.AMOUNT